import { Table, StringColumn, BooleanColumn, ReferenceColumn } from '../../db'

export const sys_user_role = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        iterativeDelete: true,
        no_table_trace: true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Role',
    name: 'sys_user_role',
    schema: {
        federated_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Federated Role ID',
            maxLength: 100,
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
            unique: true,
        }),
        includes_roles: StringColumn({
            array: true,
            label: 'Includes roles',
        }),

        scoped_admin: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If this is an Application Administrator role',
                    label: 'Application Administrator',
                    plural: 'Application Administrators',
                },
            ],
        }),
        description: StringColumn({
            attributes: {
                no_truncate: true,
            },
            label: 'Description',
            maxLength: 1000,
        }),
        elevated_privilege: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'This role is an elevated privilege',
                    label: 'Elevated privilege',
                    plural: 'Elevated privileges',
                },
            ],
        }),
        assignable_by: ReferenceColumn({
            label: [
                {
                    hint: "If the related application has Scoped administration enabled, a user needs to have the 'Assignable By' role to be able to assign this role to another user",
                    label: 'Assignable by',
                    plural: 'Assignable by',
                },
            ],
            referenceTable: 'sys_user_role',
            referenceQual:
                "javascript:if (gs.hasRole('admin')) 'sys_scope!=global'; else 'sys_scope=' + current.sys_scope;",
        }),
        suffix: StringColumn({
            label: 'Suffix',
            maxLength: 100,
        }),
        can_delegate: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Can be delegated',
                    label: 'Can delegate',
                    plural: 'Can delegates',
                },
            ],
        }),
        grantable: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Can be granted independently',
                    label: 'Grantable',
                    plural: 'Grantables',
                },
            ],
        }),
    },
    textIndex: true,
})
